
'use strict';
const catalog = [
 {id:'abgleich',label:'abgleich',protocols:['http'],instances:1,version:'v0.45.0',traffic:{http:8.2},p95:{http:86},description:'GitHub automation and webhooks'},
 {id:'bezeichner',label:'bezeichner',protocols:['http','grpc'],instances:2,version:'v1.1025.0',traffic:{http:240,grpc:940},p95:{http:42,grpc:24},description:'Identifier generation and mapping'},
 {id:'standort',label:'standort',protocols:['http','grpc'],instances:2,version:'v2.1028.0',traffic:{http:186,grpc:310},p95:{http:19,grpc:12},description:'Location information'},
 {id:'web',label:'web',protocols:['http'],instances:2,version:'v1.591.0',traffic:{http:14.6},p95:{http:8.4},description:'Website and embedded content'}
];
const state={service:'bezeichner',tab:'overview',seconds:900,instance:'all',level:'all',search:'',protocol:'all',errors:false,traceFilter:'',empty:false,paused:true,selected:null,span:0,page:0};
let plots=[], timer=null, selectedWindow=null, revision=0;
const endTime=Date.UTC(2026,10,3,10,45,0)/1000;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={log:'<path d="M4 2h8v12H4zM6 5h4M6 8h4M6 11h2"/>',trace:'<path d="M2 4h6v3H2zM5 10h7v3H5zM8 5h4M12 5v5"/>',search:'<circle cx="6.5" cy="6.5" r="4"/><path d="m10 10 4 4"/>',empty:'<path d="M2 11h3l2-6 3 9 2-6h2"/>'};return `<svg class="icon" viewBox="0 0 16 16" aria-hidden="true">${paths[name]||paths.empty}</svg>`};
function service(){return catalog.find(s=>s.id===state.service)||catalog[1]}
function short(n,d=1){return n>=1000?(n/1000).toFixed(d)+'k':n.toFixed(n<10?d:0)}
function stamp(t){return new Date(t*1000).toISOString().slice(11,19)}
function value(n,unit){if(unit==='ms')return n.toFixed(n<10?1:0);if(unit==='ratio')return n.toFixed(1);return short(n)}
function hashState(){const p=new URLSearchParams({service:state.service,view:state.tab,range:state.seconds});if(state.traceFilter)p.set('trace',state.traceFilter);if(state.instance!=='all')p.set('instance',state.instance);if(state.protocol!=='all')p.set('protocol',state.protocol);if(selectedWindow){p.set('from',Math.round(selectedWindow[0]));p.set('to',Math.round(selectedWindow[1]))}if(state.selected?.kind==='trace')p.set('detail',state.selected.id);history.replaceState(null,'','#'+p.toString())}
function readHash(){const p=new URLSearchParams(location.hash.slice(1));if(catalog.some(s=>s.id===p.get('service')))state.service=p.get('service');if(['overview','logs','traces'].includes(p.get('view')))state.tab=p.get('view');if([300,900,3600,86400].includes(Number(p.get('range'))))state.seconds=Number(p.get('range'));state.traceFilter=p.get('trace')||'';if(['0','1'].includes(p.get('instance'))&&Number(p.get('instance'))<service().instances)state.instance=p.get('instance');if(service().protocols.includes(p.get('protocol')))state.protocol=p.get('protocol');if(p.has('from')&&p.has('to')){const from=Number(p.get('from')),to=Number(p.get('to'));if(Number.isFinite(from)&&Number.isFinite(to)&&from<to)selectedWindow=[from,to]}}
function spark(color,seed){let points=[];for(let i=0;i<20;i++){let y=15+Math.sin(i*.8+seed)*5+Math.cos(i*1.7)*2;points.push((i*4)+','+y)}return `<svg class="stat-spark" viewBox="0 0 80 30" aria-hidden="true"><polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5"/></svg>`}
function makeSeries(s,p,kind){const count=45,x=[],a=[],b=[],c=[];const base=s.traffic[p]*(state.instance==='all'?1:1/s.instances);for(let i=0;i<=count;i++){let wave=1+Math.sin(i*.29+revision)*.09+Math.sin(i*1.7)*.025,spike=Math.exp(-Math.pow((i-31)/2.5,2));x.push(endTime-state.seconds+i*state.seconds/count);if(kind==='latency'){a.push(s.p95[p]*.36*wave*(1+spike*.8));b.push(s.p95[p]*wave*(1+spike*1.65));c.push(s.p95[p]*1.75*wave*(1+spike*2.3))}else if(kind==='traffic'){a.push(base*wave*(1+spike*.15))}else if(kind==='errors'){a.push(Math.max(0,base*(.0015+Math.sin(i*.5)*.0005+spike*.008)))}else{a.push(3+Math.sin(i*.37)*.25+spike*3.1)}}return kind==='latency'?[x,a,b,c]:[x,a]}
function card(label,number,unit,foot,color,seed){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${number}<small>${unit}</small></div><div class="stat-foot">${foot}</div>${spark(color,seed)}</div>`}
function stats(){const s=service(),factor=state.instance==='all'?1:1/s.instances,total=Object.values(s.traffic).reduce((a,b)=>a+b,0)*factor;let result=card('Request rate',short(total),'req/s','All configured server protocols','#4687f2',1)+card('Non-success rate','0.34','%',s.protocols.includes('grpc')?'HTTP 4xx/5xx + gRPC non-OK':'HTTP 4xx/5xx','#df6674',3);for(const p of s.protocols)result+=card(p.toUpperCase()+' latency · p95',String(s.p95[p]),'ms','Histogram across selected instances',p==='http'?'#16a99a':'#9673df',p==='http'?2:4);if(s.protocols.length===1)result+=card('Receiving instances',state.instance==='all'?String(s.instances):'1','',s.version,'#16a99a',5);return `<div class="stats">${result}</div>`}
const chartKinds=[{id:'latency',title:'Latency',unit:'ms',sub:'p95',legend:[['p50','#9cb4d6'],['p95','#16a99a'],['p99','#9673df']]},{id:'traffic',title:'Traffic',unit:'req/s',sub:'requests',legend:[['Requests / second','#4687f2']]},{id:'errors',title:'Errors',unit:'err/s',sub:'non-success',legend:[['Non-success / second','#df6674']]},{id:'spread',title:'Latency spread',unit:'ratio',sub:'p99 / p50',legend:[['p99 / p50 · queueing proxy','#cc9850']]}];
function protocolSection(p){return `<section class="protocol-section" data-protocol="${p}"><div class="section-title"><div class="section-name"><span class="protocol-symbol">${p==='http'?'↗':'⇄'}</span><h2>${p.toUpperCase()} server</h2><span class="muted" style="font-size:10px">${p==='http'?'Incoming HTTP requests':'Incoming RPC calls'}</span></div><div class="section-actions"><button class="link-button" data-action="protocol-logs" data-protocol="${p}">View logs ↗</button><button class="link-button" data-action="protocol-traces" data-protocol="${p}">View traces ↗</button></div></div><div class="charts">${chartKinds.map(k=>{const data=makeSeries(service(),p,k.id),v=data[k.id==='latency'?2:1].at(-1);return `<article class="panel"><div class="panel-head"><span class="panel-title">${k.title}</span><span class="panel-meta">${k.sub}</span></div><div class="panel-number">${value(v,k.unit)}<small>${k.unit==='ratio'?'×':k.unit}</small></div><div class="panel-legend">${k.legend.map(l=>`<span><i class="legend-dot" style="background:${l[1]}"></i>${l[0]}</span>`).join('')}</div><div class="plot" id="plot-${p}-${k.id}" role="img" aria-label="${p.toUpperCase()} ${k.title} over the selected time range"></div><div class="chart-footer"><span>UTC · drag to select</span><button data-action="protocol-traces" data-protocol="${p}">Explore ↗</button></div></article>`}).join('')}</div></section>`}
function emptyView(title,text){return `<div class="panel empty"><div class="empty-icon">${icon('empty')}</div><h3>${title}</h3><p>${text}</p></div>`}
function dataset(){const s=service(),traces=[],logs=[];const ops=s.id==='bezeichner'?['GenerateIdentifiers','MapIdentifiers','GetApplications']:s.id==='standort'?['LookupLocations','GetLocation','LookupLocations']:s.id==='web'?['GET /books','GET /','GET /robots.txt']:['POST /webhook','GET /status','GET /health'];for(let i=0;i<12;i++){const p=s.protocols[i%s.protocols.length],duration=[184.6,42.3,24.1,122.8,18.4,67.2,31.8,15.2,92.4,48.3,23.6,11.8][i],id=('4bf92f35'+s.id.length.toString(16).padStart(2,'0')+'77b34da6a3ce929d0e0e').slice(0,30)+i.toString(16).padStart(2,'0');traces.push({id,operation:ops[i%ops.length],protocol:p,duration,error:i===0||i===3,time:endTime-20-i*37,spans:p==='http'?8:3,instance:`${s.id}-${i%s.instances?'n6qx2':'k8jm4'}`})}for(let i=0;i<24;i++){const t=traces[i%traces.length],level=i%9===0?'error':i%7===0?'warn':i%11===0?'debug':'info',msg=s.id==='abgleich'?(level==='error'?'github webhook failed':'job finished'):`${t.protocol}: ${t.operation} ${level==='error'?'request failed':level==='warn'?'request completed with warning':'finished'}`;logs.push({id:i,trace:t,traceId:i%5===0&&i>0?'':t.id,level,message:msg,protocol:t.protocol,time:endTime-9-i*16,instance:`${s.id}-${i%s.instances?'n6qx2':'k8jm4'}`,duration:t.duration})}return{traces,logs}}
function instanceTable(){const s=service(),n=state.instance==='all'?s.instances:1;return `<article class="panel"><div class="table-title"><h2>Instances</h2><span class="muted" style="font-size:10px">Runtime · per instance</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Instance</th><th>Go memory</th><th>Goroutines</th><th>Go alloc / s</th></tr></thead><tbody>${Array.from({length:n},(_,i)=>`<tr><td><span class="instance-cell"><i class="dot"></i><span class="mono" style="font-size:10px">${esc(s.id)}-${(state.instance==='all'?i:Number(state.instance))?'n6qx2':'k8jm4'}</span></span></td><td>${(21.4+i*1.8).toFixed(1)} MiB</td><td>${43+i*5}</td><td>${(64+i*8).toFixed(0)} KiB</td></tr>`).join('')}</tbody></table></div></article>`}
function recentTraces(){return `<article class="panel"><div class="table-title"><h2>Recent slow traces</h2><button class="link-button" data-tab="traces">View all →</button></div><table class="data-table"><thead><tr><th>Operation</th><th>Protocol</th><th>Duration</th><th>Status</th></tr></thead><tbody>${dataset().traces.slice(0,2).map(t=>`<tr class="clickable" data-trace="${t.id}"><td>${esc(t.operation)}</td><td><span class="badge">${t.protocol.toUpperCase()}</span></td><td>${t.duration} ms</td><td><span class="status-badge ${t.error?'error':''}">${t.error?'Error':'OK'}</span></td></tr>`).join('')}</tbody></table></article>`}
function overview(){if(state.empty)return statsEmpty()+emptyView('Waiting for telemetry',`${service().label} is configured for ${service().protocols.map(p=>p.toUpperCase()).join(' and ')}. Its panels will populate when signals arrive.`);return stats()+(selectedWindow?`<div class="selection-notice"><span>Selected ${stamp(selectedWindow[0])} – ${stamp(selectedWindow[1])} UTC</span><span><button class="link-button" data-action="selected-logs">Explore logs</button> &nbsp; <button class="link-button" data-action="selected-traces">Explore traces</button> &nbsp; <button class="link-button" data-action="clear-selection">Clear</button></span></div>`:'')+service().protocols.map(protocolSection).join('')+`<div class="compact-bottom">${instanceTable()}${recentTraces()}</div>`+footer()}
function statsEmpty(){return `<div class="stats">${['Request rate','Non-success rate','Latency · p95','Receiving instances'].map(l=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value muted">—</div><div class="stat-foot">No samples in this range</div></div>`).join('')}</div>`}
function footer(){return '<div class="footer-note"><span>Sample telemetry · 3 Nov 2026 · UTC</span><span>Recent + archived data · scope preserved across views</span></div>'}
function filterBar(kind){return `<div class="query-bar"><div class="search-box">${icon('search')}<input id="search" aria-label="${kind==='logs'?'Search log messages, attributes or trace IDs':'Search operations or trace IDs'}" placeholder="${kind==='logs'?'Search messages, attributes or trace ID…':'Search operation or trace ID…'}" value="${esc(state.search)}"></div>${kind==='logs'?`<select class="control" id="level" aria-label="Log severity">${['all','error','warn','info','debug'].map(v=>`<option value="${v}" ${state.level===v?'selected':''}>${v==='all'?'All levels':v.toUpperCase()}</option>`).join('')}</select>`:''}<select class="control" id="protocol" aria-label="Server protocol"><option value="all">All protocols</option>${service().protocols.map(p=>`<option value="${p}" ${state.protocol===p?'selected':''}>${p.toUpperCase()}</option>`).join('')}</select>${kind==='traces'?`<button class="button ${state.errors?'active':''}" data-action="errors">${state.errors?'✓ ':''}Errors only</button>`:''}<button class="button" data-action="reset-filters">Reset</button></div>${state.traceFilter?`<div class="chips"><span class="chip mono">trace: ${esc(state.traceFilter.slice(0,16))}… <button data-action="clear-trace" aria-label="Remove trace filter">×</button></span></div>`:''}`}
function inScope(v){const lo=selectedWindow?selectedWindow[0]:endTime-state.seconds,hi=selectedWindow?selectedWindow[1]:endTime;return v.time>=lo&&v.time<hi&&(state.instance==='all'||v.instance===`${service().id}-${state.instance==='1'?'n6qx2':'k8jm4'}`)}
function selectionBanner(){return selectedWindow?`<div class="selection-notice"><span>Selected ${stamp(selectedWindow[0])} – ${stamp(selectedWindow[1])} UTC</span><button class="link-button" data-action="clear-selection">Clear selection</button></div>`:''}
function filteredLogs(){if(state.empty)return[];let q=state.search.toLowerCase();return dataset().logs.filter(l=>inScope(l)&&(state.level==='all'||l.level===state.level)&&(state.protocol==='all'||l.protocol===state.protocol)&&(!state.traceFilter||l.traceId===state.traceFilter)&&(!q||(l.message+' '+l.traceId+' '+l.instance).toLowerCase().includes(q)))}
function logsView(){const rows=filteredLogs(),visible=rows.slice(state.page*12,state.page*12+12);return selectionBanner()+filterBar('logs')+`<div class="query-meta"><span>${rows.length} records · newest first</span><span>Returned in 118 ms · ${state.seconds>900?'archive included':'recent window'}</span></div>`+(rows.length?`<article class="panel"><div class="table-wrap"><table class="data-table log-table"><thead><tr><th style="width:31px"></th><th>Timestamp · UTC</th><th>Level</th><th>Message</th><th>Trace ID</th></tr></thead><tbody>${visible.map(l=>`<tr class="clickable" data-log="${l.id}"><td class="muted">›</td><td class="timestamp">${stamp(l.time)}.${String(735+l.id*7).slice(0,3)}</td><td><span class="level ${l.level}">${l.level.toUpperCase()}</span></td><td class="message">${esc(l.message)}<span class="inline-tag">${l.protocol}</span></td><td>${l.traceId?`<button class="trace-link" data-trace="${l.traceId}">${l.traceId.slice(0,12)}… ↗</button>`:'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div><div class="result-footer"><span>Showing ${state.page*12+1}–${Math.min(rows.length,state.page*12+12)} of ${rows.length} records</span><span><button class="pagination-button" data-action="previous" ${state.page===0?'disabled':''}>Previous</button> <button class="pagination-button" data-action="next" ${(state.page+1)*12>=rows.length?'disabled':''}>Next</button></span></div></article>`:emptyView('No matching logs',state.empty?'Waiting for log records from this service.':'Try another level, time range, or search.'))+footer()}
function filteredTraces(){if(state.empty)return[];const q=state.search.toLowerCase();return dataset().traces.filter(t=>inScope(t)&&(state.protocol==='all'||t.protocol===state.protocol)&&(!state.errors||t.error)&&(!state.traceFilter||t.id===state.traceFilter)&&(!q||(t.operation+' '+t.id).toLowerCase().includes(q)))}
function tracesView(){const traces=filteredTraces();return selectionBanner()+filterBar('traces')+`<div class="query-meta"><span>${traces.length} sampled traces · newest first</span><span>Click a trace to inspect its timeline</span></div>`+(traces.length?`<article class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Operation</th><th>Started · UTC</th><th>Protocol</th><th>Duration</th><th>Spans</th><th>Status</th><th>Trace ID</th></tr></thead><tbody>${traces.map(t=>`<tr class="clickable" data-trace="${t.id}"><td style="font-weight:500">${esc(t.operation)}</td><td class="mono muted" style="font-size:10px">${stamp(t.time)}</td><td><span class="badge">${t.protocol.toUpperCase()}</span></td><td><div class="duration"><span style="min-width:51px">${t.duration} ms</span><span class="duration-track"><span class="${t.error?'bad':''}" style="width:${Math.max(4,t.duration/190*100)}%"></span></span></div></td><td class="muted">${t.spans}</td><td><span class="status-badge ${t.error?'error':''}">${t.error?(t.protocol==='grpc'?'DEADLINE_EXCEEDED':'HTTP 500'):'OK'}</span></td><td class="mono muted" style="font-size:10px">${t.id.slice(0,12)}…</td></tr>`).join('')}</tbody></table></div><div class="result-footer"><span>Sampling applies to traces; request metrics include all observed requests.</span><span>${traces.length} example traces</span></div></article>`:emptyView('No matching traces',state.empty?'Waiting for traces from this service.':'Try clearing the error or protocol filter.'))+footer()}
function renderCharts(){if(state.tab!=='overview'||state.empty)return;for(const p of service().protocols){for(const k of chartKinds){const el=$('plot-'+p+'-'+k.id);const data=makeSeries(service(),p,k.id),colors=k.legend.map(v=>v[1]);const opts={width:Math.max(170,el.clientWidth-10),height:116,padding:[7,7,0,0],legend:{show:false},cursor:{sync:{key:'service-overview'}},select:{show:true},scales:{x:{time:true},y:{auto:true,range:(u,min,max)=>[0,Math.max(.001,max*1.14)]}},series:[{},...colors.map((c,i)=>({label:k.legend[i][0],stroke:c,width:i===1?1.9:1.4,fill:colors.length===1?c+'0e':undefined,points:{show:false}}))],axes:[{size:28,stroke:'#96a4b4',font:'9px -apple-system, sans-serif',grid:{show:false},ticks:{show:false},space:70,values:(u,vals)=>vals.map(v=>stamp(v).slice(0,5))},{size:35,stroke:'#9ba7b6',font:'9px -apple-system, sans-serif',grid:{stroke:'#edf1f6',width:1},ticks:{show:false},values:(u,vals)=>vals.map(v=>v>=1000?(v/1000).toFixed(0)+'k':v<1?v.toFixed(2):v.toFixed(v<10?1:0))}],hooks:{setSelect:[u=>{if(u.select.width>12){selectedWindow=[u.posToVal(u.select.left,'x'),u.posToVal(u.select.left+u.select.width,'x')];setTimeout(()=>render(),0)}}]}};plots.push(new uPlot(opts,data,el))}}}
function render(){for(const p of plots)p.destroy();plots=[];const s=service();$('service-list').innerHTML=catalog.map(v=>`<button class="service-button ${v.id===s.id?'active':''}" data-service="${v.id}" aria-current="${v.id===s.id?'page':'false'}"><span class="dot"></span><span class="service-name">${v.label}</span><span class="nav-badge">${v.protocols.length===2?'H+G':'H'}</span></button>`).join('');$('breadcrumb').textContent=s.label;$('service-title').textContent=s.label;$('protocol-badges').innerHTML=s.protocols.map(p=>`<span class="badge" style="margin-left:4px">${p.toUpperCase()}</span>`).join('');$('service-subtitle').textContent=s.description+' · '+s.version+' · '+s.instances+' '+(s.instances===1?'instance':'instances');$('current-window').textContent=stamp(endTime-state.seconds)+' – '+stamp(endTime)+' UTC';$('instance').innerHTML=`<option value="all">All instances (${s.instances})</option>`+Array.from({length:s.instances},(_,i)=>`<option value="${i}" ${state.instance===String(i)?'selected':''}>${s.id}-${i?'n6qx2':'k8jm4'}</option>`).join('');$('time-range').value=String(state.seconds);document.querySelectorAll('.tab').forEach(b=>{const active=b.dataset.tab===state.tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});$('view').setAttribute('aria-labelledby','tab-'+state.tab);$('view').innerHTML=state.tab==='overview'?overview():state.tab==='logs'?logsView():tracesView();const search=$('search');if(search)search.addEventListener('input',e=>{state.search=e.target.value;state.page=0;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos)});const lev=$('level');if(lev)lev.addEventListener('change',e=>{state.level=e.target.value;state.page=0;render()});const proto=$('protocol');if(proto)proto.addEventListener('change',e=>{state.protocol=e.target.value;state.page=0;render()});renderCharts();hashState();document.body.dataset.ready='true'}
function attributes(entries){return `<table class="attribute-table">${entries.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</table>`}
function inspectorShell(type,title,meta,content){return `<div class="inspector-backdrop" data-action="close"></div><aside class="inspector" aria-label="${type} details"><div class="inspector-top"><div class="inspector-topline"><span>${type.toUpperCase()} DETAILS</span><button class="close" data-action="close" aria-label="Close details">×</button></div><h2>${esc(title)}</h2>${meta}</div><div class="inspector-content">${content}</div></aside>`}
function showLog(id){const l=dataset().logs.find(v=>v.id===Number(id));if(!l)return;state.selected={kind:'log',id};$('inspector-root').innerHTML=inspectorShell('Log',l.message,`<span class="level ${l.level}">${l.level.toUpperCase()}</span><span class="muted" style="font-size:11px">3 Nov 2026 · ${stamp(l.time)}.735 UTC</span>`,`<div class="message-box">${esc(l.message)}</div><div class="inspector-actions">${l.traceId?`<button class="button primary" data-trace="${l.traceId}">${icon('trace')}Open trace</button>`:''}<button class="button" data-action="context-logs">Surrounding logs</button></div><div class="detail-section">Record attributes</div>${attributes([['service.name',service().label],['service.instance.id',l.instance],['deployment.environment.name','production'],['system',l.protocol],['duration',l.duration+'ms'],['code',l.level==='error'?(l.protocol==='grpc'?'DeadlineExceeded':'500'):'OK'],['trace_id',l.traceId||'Not present'],['request-id','req_01JCN7X4K8ZQ6']])}`)}
function spanData(t){if(t.protocol==='grpc')return[{name:t.operation,svc:'internal-client',start:0,width:100,root:true},{name:t.operation,svc:service().label,start:7,width:86,bad:t.error},{name:'grpc.status',svc:service().label,start:94,width:5}];return[{name:t.operation,svc:'internal-client',start:0,width:100,root:true},{name:'http.getconn',svc:'internal-client',start:1,width:13},{name:'http.dns',svc:'internal-client',start:2,width:4},{name:'http.connect',svc:'internal-client',start:7,width:5},{name:'http.tls',svc:'internal-client',start:12,width:7},{name:t.operation,svc:service().label,start:20,width:70,bad:t.error},{name:'http.receive',svc:'internal-client',start:91,width:8},{name:'http.close',svc:'internal-client',start:99,width:1}]}
function showTrace(id,changeTab=true){const t=dataset().traces.find(v=>v.id===id);if(!t)return;if(changeTab){state.tab='traces';state.selected=null;render()}state.selected={kind:'trace',id};const spans=spanData(t),selected=spans[Math.min(state.span,spans.length-1)];$('inspector-root').innerHTML=inspectorShell('Trace',t.operation,`<div class="detail-id"><span class="mono">${t.id}</span><button class="link-button" data-action="copy-trace" data-id="${t.id}">Copy</button><span class="status-badge ${t.error?'error':''}">${t.error?'Error':'OK'}</span></div><div class="trace-stats"><div><div class="value">${t.duration} <span style="font-size:11px">ms</span></div><div class="label">Duration</div></div><div><div class="value">${spans.length}</div><div class="label">Spans</div></div><div><div class="value">2</div><div class="label">Services</div></div></div>`,`<div style="display:flex;align-items:center;justify-content:space-between"><span style="font-size:12px;font-weight:500">Span timeline</span><button class="link-button" data-action="related-logs" data-id="${t.id}">View related logs ↗</button></div><p class="muted" style="font-size:10px;margin:5px 0 16px">Client and server spans · click a span to inspect attributes</p><div class="waterfall-header"><span>Service / operation</span><span class="waterfall-axis"><span>0 ms</span><span>${(t.duration/2).toFixed(1)}</span><span>${t.duration} ms</span></span></div>${spans.map((v,i)=>`<div class="span-row ${i===state.span?'selected':''}" data-span="${i}"><div class="span-name" style="padding-left:${i===0?0:12}px">${i===0?'⌄ ':'↳ '}${esc(v.name)}<small>${esc(v.svc)}</small></div><div class="span-track"><span class="span-bar ${v.root?'root':''} ${v.bad?'bad':''}" style="left:${v.start}%;width:${v.width}%"></span><span class="span-ms">${(v.width*t.duration/100).toFixed(1)} ms</span></div></div>`).join('')}<div class="detail-section">Selected span · ${esc(selected.name)}</div>${attributes([['service.name',selected.svc],['span.kind',selected.root?'CLIENT':'SERVER'],['duration',(selected.width*t.duration/100).toFixed(1)+'ms'],['status',selected.bad?'ERROR':'OK'],[t.protocol==='http'?'http.request.method':'rpc.method',t.protocol==='http'?'POST':t.operation],['deployment.environment.name','production']])}${t.error?'<div class="detail-section">Error event</div><div class="message-box">context deadline exceeded<br>request exceeded its configured deadline</div>':''}<div class="inspector-actions"><button class="button primary" data-action="related-logs" data-id="${t.id}">${icon('log')}Related logs</button><button class="button" data-action="close">Back to traces</button></div>`);hashState()}
function closeInspector(){$('inspector-root').innerHTML='';state.selected=null;state.span=0;hashState()}
function toast(text){$('toast-root').innerHTML=`<div class="toast">${esc(text)}</div>`;setTimeout(()=>$('toast-root').innerHTML='',2200)}
function switchTab(tab){closeInspector();state.tab=tab;state.search='';state.page=0;render()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-service],[data-tab],[data-action],[data-log],[data-trace],[data-span]');if(!el)return;if(el.dataset.service){closeInspector();state.service=el.dataset.service;state.instance='all';state.protocol='all';state.traceFilter='';state.search='';state.page=0;selectedWindow=null;render();return}if(el.dataset.tab){switchTab(el.dataset.tab);return}if(el.dataset.trace){state.span=0;showTrace(el.dataset.trace);return}if(el.dataset.log){showLog(el.dataset.log);return}if(el.dataset.span){state.span=Number(el.dataset.span);showTrace(state.selected.id,false);return}switch(el.dataset.action){case'close':closeInspector();break;case'empty':state.empty=!state.empty;el.textContent=state.empty?'Show sample data':'Show empty state';closeInspector();render();break;case'refresh':revision++;render();toast('Sample view refreshed');break;case'auto':state.paused=!state.paused;$('auto-refresh').textContent=state.paused?'Ⅱ Paused':'● Auto · 5s';$('auto-refresh').classList.toggle('active',!state.paused);if(timer)clearInterval(timer);if(!state.paused)timer=setInterval(()=>{revision++;if(!state.selected)render()},5000);break;case'protocol-logs':state.protocol=el.dataset.protocol;state.traceFilter='';switchTab('logs');break;case'protocol-traces':state.protocol=el.dataset.protocol;state.traceFilter='';switchTab('traces');break;case'errors':state.errors=!state.errors;render();break;case'reset-filters':state.search='';state.protocol='all';state.level='all';state.errors=false;state.traceFilter='';state.page=0;render();break;case'clear-trace':state.traceFilter='';render();break;case'next':state.page++;render();break;case'previous':state.page=Math.max(0,state.page-1);render();break;case'related-logs':state.traceFilter=el.dataset.id;state.level='all';state.protocol='all';switchTab('logs');break;case'context-logs':{const record=dataset().logs.find(l=>l.id===Number(state.selected?.id));if(record)selectedWindow=[record.time-60,record.time+60];state.page=0;state.traceFilter='';state.search='';state.level='all';closeInspector();state.tab='logs';render();break;}case'copy-trace':if(navigator.clipboard)navigator.clipboard.writeText(el.dataset.id).then(()=>toast('Trace ID copied')).catch(()=>toast(el.dataset.id));else toast(el.dataset.id);break;case'clear-selection':selectedWindow=null;render();break;case'selected-logs':switchTab('logs');break;case'selected-traces':switchTab('traces');break;case'collector':$('collector-root').innerHTML=$('collector-root').innerHTML?'':`<div class="collector-popover"><h3>Collector status <button class="close" data-action="collector" style="float:right">×</button></h3><dl><dt>Last received</dt><dd>3 seconds ago</dd><dt>Pending archive</dt><dd>28 seconds</dd><dt>Last archive</dt><dd>10:44:32 UTC</dd><dt>Receiving services</dt><dd>4 / 4</dd><dt>Query coverage</dt><dd>Complete</dd></dl><p class="muted" style="margin-bottom:0;font-size:10px">Example collector state. This preview is not connected to live services.</p></div>`;break}});
$('time-range').addEventListener('change',e=>{state.seconds=Number(e.target.value);state.page=0;selectedWindow=null;render()});
$('instance').addEventListener('change',e=>{state.instance=e.target.value;state.page=0;render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeInspector();$('collector-root').innerHTML=''}});
window.addEventListener('resize',()=>{for(const p of plots){const width=p.root.parentElement.clientWidth-10;p.setSize({width:Math.max(170,width),height:116})}});
window.addEventListener('error',e=>{document.body.dataset.error=e.message});
const initialDetail=new URLSearchParams(location.hash.slice(1)).get('detail');
readHash();render();
if(initialDetail)showTrace(initialDetail,false);else if(state.traceFilter&&state.tab==='traces')showTrace(state.traceFilter,false);
